from collections import deque
class PageFetcher:
    def __init__(self, fetch):
        self.fetch, self.buf, self.token, self.started = fetch, deque(), None, False
    def fill(self):
        if self.started and self.token is None:
            return False
        items, self.token = self.fetch(self.token)
        self.started = True
        self.buf.extend(items)
        return True

